import{_ as t,c as e,o,ae as c}from"./chunks/framework.CFeneB-q.js";const I=JSON.parse('{"title":"PC 端 · 环境变量清单","description":"","frontmatter":{},"headers":[],"relativePath":"pc/references/env-vars.md","filePath":"pc/references/env-vars.md","lastUpdated":1789438865000}'),a={name:"pc/references/env-vars.md"};function r(_,d,n,P,i,E){return o(),e("div",null,[...d[0]||(d[0]=[c('<h1 id="pc-端-·-环境变量清单" tabindex="-1">PC 端 · 环境变量清单 <a class="header-anchor" href="#pc-端-·-环境变量清单" aria-label="Permalink to &quot;PC 端 · 环境变量清单&quot;">​</a></h1><blockquote><p>全量变量整理自 <code>keystone-deliver-ui</code> 的 <code>.env</code> 五件套（2026-09-16 核对）。<strong>密钥类变量一律不写值</strong>（下表以 <code>***</code> 表示）。两个工具脚本会改写这些文件：<code>pnpm switch:api</code> 改写各环境 <code>VITE_APP_BASE_API</code>；<code>pnpm start</code>（views-switcher）写入 <code>VITE_BUILD_VIEWS</code>。</p></blockquote><h2 id="env-全局-所有模式生效" tabindex="-1"><code>.env</code>（全局，所有模式生效） <a class="header-anchor" href="#env-全局-所有模式生效" aria-label="Permalink to &quot;`.env`（全局，所有模式生效）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>用途</th><th>示例值</th></tr></thead><tbody><tr><td><code>VITE_APP_TITLE</code></td><td>页面标题（中文）</td><td><code>工程信息化管理平台</code></td></tr><tr><td><code>VITE_APP_TITLE_EN</code></td><td>页面标题（英文）</td><td><code>Engineering project informationized management</code></td></tr><tr><td><code>VITE_APP_LOGO</code></td><td>平台 logo 地址</td><td>OSS 地址</td></tr><tr><td><code>VITE_PORT</code></td><td>dev 服务端口</td><td><code>8193</code></td></tr><tr><td><code>VITE_PUBLIC_PATH</code></td><td>资源公共路径</td><td><code>/</code></td></tr><tr><td><code>VITE_APP_OSS_URL</code></td><td>阿里云正式环境静态资源 OSS 前缀</td><td><code>https://e9-matchbim-bucket.oss-cn-hangzhou.aliyuncs.com</code></td></tr><tr><td><code>VITE_APP_GEOMETRY_API</code></td><td>几何接口 baseURL（http 层按 <code>requestType: &#39;geometry&#39;</code> 分流）</td><td><code>https://airoad.tech/prod-api/</code></td></tr><tr><td><code>VITE_APP_EZVIDEO_API</code></td><td>萤石视频接口（<code>requestType: &#39;ezvideo&#39;</code> 分流）</td><td><code>https://open.ys7.com/api</code></td></tr><tr><td><code>VITE_APP_LECHANGE_API</code> / <code>VITE_APP_LECHANGE_URL</code></td><td>乐橙云接口代理前缀 / 真实地址</td><td><code>/lechange</code> / <code>https://openapi.lechange.cn</code></td></tr><tr><td><code>VITE_APP_TPLINK_API</code> / <code>VITE_APP_TPLINK_URL</code></td><td>TPLink 云接口代理前缀 / 真实地址</td><td><code>/tplink</code> / <code>https://api-smbcloud.tp-link.com.cn</code></td></tr><tr><td><code>VITE_APP_YUNZHU_API</code></td><td>云筑接口代理前缀</td><td><code>/yunzhu</code></td></tr><tr><td><code>VITE_BUILD_VIEWS</code></td><td>参与编译的业务视图别名（逗号分隔）</td><td>空串 / <code>fc,pzgc,st</code>（由 <code>pnpm start</code> 写入）</td></tr><tr><td>地图 Key（百度/高德/Google）</td><td>已注释停用；启用时写入对应变量</td><td><code>***</code></td></tr></tbody></table><h2 id="env-development-开发环境" tabindex="-1"><code>.env.development</code>（开发环境） <a class="header-anchor" href="#env-development-开发环境" aria-label="Permalink to &quot;`.env.development`（开发环境）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>用途</th><th>示例值</th></tr></thead><tbody><tr><td><code>VITE_ENV</code></td><td>环境标识</td><td><code>development</code></td></tr><tr><td><code>VITE_APP_BASE_API</code></td><td>请求基址（<code>switch:api</code> 改写目标）</td><td><code>http://keystone.dev01.matchbim.cn/api</code></td></tr><tr><td><code>VITE_APP_KEYSTONE_API</code> … <code>VITE_APP_RUNCHENG_API</code></td><td>各客户项目 API（switch:api 的发现源，8 键）</td><td><code>http://pzgc.dev01.matchbim.cn/api</code> 等</td></tr><tr><td><code>VITE_APP_YUNZHU_API</code> / <code>VITE_APP_YUNZHU_URL</code></td><td>云筑代理前缀 / 地址</td><td><code>/yunzhu</code> / <code>https://dw.yzw.cn/st/open</code></td></tr><tr><td><code>VITE_APP_OSSUPLOAD_URL</code></td><td>直传 OSS 开发环境地址</td><td><code>https://e9-matchbim-bucket-dev.oss-cn-hangzhou.aliyuncs.com/</code></td></tr><tr><td><code>VITE_APP_USE_MOCK</code></td><td>mock 开关</td><td><code>false</code></td></tr><tr><td><code>VITE_BUILD_VIEWS</code></td><td>业务视图选择结果</td><td><code>&#39;&#39;</code></td></tr></tbody></table><h2 id="env-location-本地联调-pnpm-start-默认" tabindex="-1"><code>.env.location</code>（本地联调，<code>pnpm start</code> 默认） <a class="header-anchor" href="#env-location-本地联调-pnpm-start-默认" aria-label="Permalink to &quot;`.env.location`（本地联调，`pnpm start` 默认）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>用途</th><th>示例值</th></tr></thead><tbody><tr><td><code>VITE_ENV</code></td><td><code>location</code></td><td>—</td></tr><tr><td><code>VITE_APP_BASE_API</code></td><td>请求前缀（走 Vite 代理）</td><td><code>/dev-api</code></td></tr><tr><td><code>VITE_APP_BASE_URL</code></td><td>代理目标（本地/某环境后端）</td><td><code>http://192.168.x.x:21002/api</code></td></tr><tr><td><code>VITE_APP_SSO_URL</code></td><td>本地 SSO 平台地址</td><td><code>http://192.168.x.x:8192</code></td></tr><tr><td><code>VITE_APP_USE_SSO</code></td><td>是否启用 SSO 跳转</td><td><code>false</code></td></tr><tr><td><code>VITE_APP_USE_MOCK</code></td><td>mock 开关</td><td><code>false</code></td></tr><tr><td><code>VITE_APP_YUNZHU_URL</code> / <code>VITE_APP_YUNZHU_CLIENTCODE</code> / <code>VITE_APP_YUNZHU_PRIVATEKEY</code> / <code>VITE_APP_YUNZHU_PROJECTKEY</code></td><td>云筑对接生产配置</td><td><code>***</code></td></tr><tr><td><code>VITE_BUILD_VIEWS</code></td><td>业务视图选择结果</td><td><code>&#39;&#39;</code></td></tr></tbody></table><h2 id="env-staging-测试环境" tabindex="-1"><code>.env.staging</code>（测试环境） <a class="header-anchor" href="#env-staging-测试环境" aria-label="Permalink to &quot;`.env.staging`（测试环境）&quot;">​</a></h2><p><code>VITE_ENV=staging</code>；<code>VITE_APP_BASE_API=http://keystone.tet.deliver.matchbim.cn/api</code>；<code>VITE_APP_KEYSTONE/PZGC/SHATE/DEMO_API</code> 四键（staging 域名）；<code>VITE_APP_USE_MOCK=false</code>。</p><h2 id="env-production-生产环境" tabindex="-1"><code>.env.production</code>（生产环境） <a class="header-anchor" href="#env-production-生产环境" aria-label="Permalink to &quot;`.env.production`（生产环境）&quot;">​</a></h2><p><code>VITE_ENV=production</code>；<code>VITE_APP_BASE_API=https://keystone.matchbim.cn/api</code>；八个客户键中 <code>VITE_APP_SAHW_API=http://37.224.115.117:10099/api</code>（sahw 仅生产有）；云筑生产配置（<code>***</code>）；<code>VITE_BUILD_VIEWS=&#39;st&#39;</code>（以交付时选择为准）。</p><h2 id="与基座-e9-delivery-ui-的差异" tabindex="-1">与基座 e9-delivery-ui 的差异 <a class="header-anchor" href="#与基座-e9-delivery-ui-的差异" aria-label="Permalink to &quot;与基座 e9-delivery-ui 的差异&quot;">​</a></h2><p>基座项目无各客户 <code>VITE_APP_&lt;KEY&gt;_API</code> 键与 <code>VITE_BUILD_VIEWS</code>；多出的地图 Key 变量：<code>VITE_APP_BAIDU_API_KEY</code>、<code>VITE_APP_GOOGLE_API_KEY</code>（值 <code>***</code>）。其余基础变量语义一致。</p>',14)])])}const p=t(a,[["render",r]]);export{I as __pageData,p as default};
